<script setup lang="ts">
import { computed, ref } from 'vue'
const props = defineProps<{resource:'payroll-rate'|'billing-rate';items:any[];allItems:any[];agencyPositions:any[];regionalRates:any[];filters:any;loading:boolean}>()
const isPayroll=computed(()=>props.resource==='payroll-rate')
const rateName=computed(()=>isPayroll.value?'Payroll':'Billing')
const idKey=computed(()=>isPayroll.value?'PayrollRateID':'BillingRateID')
const emit = defineEmits<{add:[group:any];edit:[item:any];update:[item:any];history:[item:any];deactivate:[item:any];navigate:[opened:boolean];regional:[mode:string,group?:any]}>()
const selectedKey = ref('')
const money = (value:any) => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value)||0)
const date = (value:any) => {const day=String(value||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(day)?new Intl.DateTimeFormat('en-PH',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(day+'T00:00:00Z')):'Not set'}
const agencyFor = (item:any) => props.agencyPositions.find(position=>Number(position.AgencyPositionID)===Number(item.AgencyPositionID)) || props.agencyPositions.find(position=>position.AgencyName===item.AgencyName)
const keyFor = (item:any) => JSON.stringify([String(item.AgencyID??agencyFor(item)?.AgencyID??item.AgencyName),item.RegionID==null?'all':String(item.RegionID)])
function groupRows(rows:any[],masters:any[]=props.regionalRates){
 const groups=new Map<string,any>()
 for(const item of [...masters,...rows]){const key=keyFor(item);if(!groups.has(key))groups.set(key,{key,AgencyID:item.AgencyID??agencyFor(item)?.AgencyID??null,AgencyName:item.AgencyName,RegionID:item.RegionID,RegionCode:item.RegionCode,RegionName:item.RegionName||'All regions',items:[]});if(item[idKey.value]!=null)groups.get(key).items.push(item);else groups.get(key).parent=item}
 return [...groups.values()].map(group=>({...group,items:group.items.sort((a:any,b:any)=>String(a.PositionName).localeCompare(String(b.PositionName))||Number(a[idKey.value])-Number(b[idKey.value]))})).sort((a,b)=>String(a.AgencyName).localeCompare(String(b.AgencyName))||(String(a.RegionCode)==='13'?-1:String(b.RegionCode)==='13'?1:String(a.RegionName).localeCompare(String(b.RegionName))))
}
const allGroups=computed(()=>groupRows(props.allItems))
const filteredMasters=computed(()=>props.regionalRates.filter(parent=>{
 const f=props.filters,words=String(f.search||'').trim().toLowerCase().split(/\s+/).filter(Boolean)
 return !f.positionFilter&&(!f.agencyFilter||parent.AgencyName===f.agencyFilter)&&(!f.regionFilter||String(parent.RegionID??'')===f.regionFilter)&&(!f.statusFilter||parent.Status===f.statusFilter)&&words.every((word:string)=>[parent.AgencyName,parent.RegionName,parent.RegionCode].join(' ').toLowerCase().includes(word))
}))
const agencies=computed(()=>{const result=new Map<string,any>();for(const group of groupRows(props.items,filteredMasters.value)){const key=String(group.AgencyID||group.AgencyName);if(!result.has(key))result.set(key,{key,name:group.AgencyName,groups:[]});result.get(key).groups.push(group)}return [...result.values()]})
const selected=computed(()=>allGroups.value.find(group=>group.key===selectedKey.value)||null)
const visibleRows=computed(()=>selected.value?props.items.filter(item=>keyFor(item)===selectedKey.value):[])
const count=(items:any[])=>new Set(items.map(item=>item.AgencyPositionID)).size
const current=(item:any,field:string)=>item.CurrentRate?.[field]??item[field]??0
const range=(group:any)=>{const amounts=group.items.map((item:any)=>Number(current(item,'RegularRate'))),min=Math.min(...amounts),max=Math.max(...amounts);if(!amounts.length)return 'No rates';return min===max?money(min):money(min)+' \u2013 '+money(max)}
const regionCode=(group:any)=>String(group.RegionCode)==='13'?'NCR':group.RegionCode?'Region '+group.RegionCode:'General'
const actions=[{key:'edit',label:'Edit current rate',path:'M12 20h9M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4L16.5 3.5Z'},
 {key:'update',label:'Update with effective date',path:'M5 4h14v17H5zM8 2v4M16 2v4M5 9h14M12 12v6M9 15h6'},
 {key:'history',label:'View rate history',path:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'},
 {key:'deactivate',label:'Deactivate rate',path:'M5.6 5.6l12.8 12.8M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'}]
function act(action:string,item:any){if(action==='edit')emit('edit',item);else if(action==='update')emit('update',item);else if(action==='history')emit('history',item);else emit('deactivate',item)}
</script>

<template>
 <section class="rate-groups" :aria-label="rateName+' rates by agency and region'">
  <p v-if="loading" class="empty" role="status">Loading {{rateName.toLowerCase()}} rates...</p>
  <template v-else-if="selected">
   <button class="back" type="button" @click="selectedKey='';emit('navigate',false)">&larr; All agencies and regions</button>
   <header class="detail-head"><div><p class="eyebrow">{{selected.AgencyName}}</p><h2>{{regionCode(selected)}} position rates</h2><p class="region-name">{{selected.RegionName}}</p></div><button class="primary" type="button" :disabled="!selected.AgencyID||(isPayroll&&!selected.parent)" @click="emit('add',selected)">+ Add position rate</button></header>
   <section v-if="isPayroll" class="regional-summary"><div v-if="selected.parent"><p class="eyebrow">REGION RATE / HOUR</p><strong>{{selected.parent.CurrentRate?money(selected.parent.CurrentRate.RegularRate):'Not effective yet'}}</strong><small>Effective {{date((selected.parent.CurrentRate||selected.parent).EffectiveDate)}}</small><small v-if="selected.parent.NextEffectiveDate">Next update: {{date(selected.parent.NextEffectiveDate)}}</small></div><p v-else class="region-name">Set up the region rate to use it as the base for position rates.</p><div v-if="selected.parent" class="regional-buttons"><button class="secondary" :disabled="!selected.parent.CurrentRate" @click="emit('regional','current',selected.parent)">Edit region rate</button><button class="secondary" @click="emit('regional','version',selected.parent)">Dated update</button><button class="secondary" @click="emit('regional','history',selected.parent)">Region history</button></div><button v-else class="secondary" @click="emit('regional','create',selected)">Set up region rate</button></section>
   <section v-else class="regional-summary"><div><p class="eyebrow">BILLING RATES / HOUR</p><strong>{{range(selected)}}</strong><small>{{count(selected.items)}} {{count(selected.items)===1?'position':'positions'}} in {{selected.RegionName}}</small></div><p class="region-name">Each position uses its saved billing rates.</p></section>
   <p class="detail-note">{{isPayroll?"Position fields follow the region rate and its effective updates. Enable Custom amount for a position's special rate or allowance.":'Review billing rates by position. Use Edit for corrections, Update for a new effective date, or History to review previous amounts.'}}</p>
   <div class="detail-meta"><strong>{{count(visibleRows)}} {{count(visibleRows)===1?'position':'positions'}}</strong><span>{{visibleRows.length}} of {{selected.items.length}} rate records shown</span></div>
   <p v-if="!visibleRows.length" class="empty">No position rates match the current filters.</p>
   <div v-else class="position-table-wrap"><table class="position-table"><thead><tr><th>Position</th><th>Regular / hour</th><th>OT / hour</th><th>{{isPayroll?'Allowance / cutoff':'Night diff / hour'}}</th><th>Effective date</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in visibleRows" :key="item[idKey]"><td><strong>{{item.PositionName}}</strong><small>{{item.LinkedSites||0}} linked {{Number(item.LinkedSites)===1?'site':'sites'}}</small></td><td class="amount">{{money(current(item,'RegularRate'))}}</td><td class="amount">{{money(current(item,'OTRate'))}}</td><td class="amount">{{money(current(item,isPayroll?'Allowance':'NightDiffRate'))}}</td><td>{{date(item.CurrentRate?.EffectiveDate??item.EffectiveDate)}}<small v-if="item.NextEffectiveDate">Next: {{date(item.NextEffectiveDate)}}</small></td><td><span class="status" :class="{inactive:item.Status!=='Active'}">{{item.Status}}</span></td><td><div class="actions"><button v-for="action in actions" :key="action.key" type="button" :title="action.label" :aria-label="action.label+' for '+item.PositionName" :disabled="action.key!=='history'&&item.Status!=='Active'" :class="{danger:action.key==='deactivate'}" @click="act(action.key,item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="action.path"/></svg></button></div></td></tr></tbody></table></div>
   <div class="position-cards"><article v-for="item in visibleRows" :key="item[idKey]" class="position-card"><header><strong>{{item.PositionName}}</strong><span class="status" :class="{inactive:item.Status!=='Active'}">{{item.Status}}</span></header><dl><div><dt>Regular / hour</dt><dd>{{money(current(item,'RegularRate'))}}</dd></div><div><dt>OT / hour</dt><dd>{{money(current(item,'OTRate'))}}</dd></div><div><dt>{{isPayroll?'Allowance / cutoff':'Night diff / hour'}}</dt><dd>{{money(current(item,isPayroll?'Allowance':'NightDiffRate'))}}</dd></div></dl><p class="effective">Effective {{date(item.CurrentRate?.EffectiveDate??item.EffectiveDate)}}<span v-if="item.NextEffectiveDate"> &middot; Next {{date(item.NextEffectiveDate)}}</span></p><footer class="actions"><button v-for="action in actions" :key="action.key" type="button" :title="action.label" :aria-label="action.label+' for '+item.PositionName" :disabled="action.key!=='history'&&item.Status!=='Active'" @click="act(action.key,item)"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="action.path"/></svg></button></footer></article></div>
  </template>
  <template v-else>
   <div class="overview-note"><div><strong>Region rates</strong><p>{{isPayroll?'Manage the regional base and its effective updates, then open its position rates.':'Choose an agency and region, then open its position billing rates.'}}</p></div><span>{{groupRows(items,filteredMasters).length}} groups</span></div>
   <p v-if="!agencies.length" class="empty">{{allItems.length?'No rate groups match the current filters.':isPayroll?'No payroll rates yet. Add a region rate to get started.':'No billing rates yet. Add a rate to get started.'}}</p>
   <section v-for="agency in agencies" :key="agency.key" class="agency-group"><header class="agency-head"><span class="agency-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 21V3h11v18M15 9h5v12M8 7h3M8 11h3M8 15h3M2 21h20"/></svg></span><div><h2>{{agency.name}}</h2><p>{{agency.groups.length}} {{agency.groups.length===1?'region':'regions'}} &middot; {{count(agency.groups.flatMap((group:any)=>group.items))}} {{count(agency.groups.flatMap((group:any)=>group.items))===1?'position':'positions'}}</p></div></header><article v-for="group in agency.groups" :key="group.key" class="region-row"><div class="region-identity"><span class="region-tag">{{regionCode(group)}}</span><div><h3>{{group.RegionName}}</h3><p>{{count(group.items)}} {{count(group.items)===1?'position':'positions'}} &middot; {{group.items.filter((item:any)=>item.Status==='Active').length}} active</p></div></div><div class="range"><span>{{isPayroll?'Region rate / hour':'Billing rates / hour'}}</span><strong>{{!isPayroll?range(group):group.parent?.CurrentRate?money(group.parent.CurrentRate.RegularRate):group.parent?'Not effective yet':'Not set up'}}</strong><small v-if="isPayroll&&group.parent">Effective {{date((group.parent.CurrentRate||group.parent).EffectiveDate)}}</small></div><div class="region-controls"><button class="secondary" type="button" :aria-label="'View '+agency.name+' '+regionCode(group)+' position rates'" @click="selectedKey=group.key;emit('navigate',true)">View position rates <span aria-hidden="true">&rarr;</span></button><div v-if="isPayroll&&group.parent" class="actions"><button v-for="action in actions.slice(0,3)" :key="action.key" :title="action.label" :aria-label="action.label+' for '+agency.name+' '+regionCode(group)+' region'" :disabled="action.key==='edit'&&!group.parent.CurrentRate" @click="emit('regional',action.key==='edit'?'current':action.key==='update'?'version':'history',group.parent)"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="action.path"/></svg></button></div><button v-else-if="isPayroll" class="setup-link" @click="emit('regional','create',group)">Set up region rate</button></div></article></section>
  </template>
 </section>
</template>

<style scoped>
.rate-groups{color:var(--theme-ink,#173457);font-family:Inter,system-ui,sans-serif}.rate-groups *{box-sizing:border-box}button{font:inherit;cursor:pointer}button:focus-visible{outline:3px solid #a9c4ff;outline-offset:3px}button:disabled{opacity:.45;cursor:default}svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.overview-note{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:22px 0 18px}.overview-note strong{font-size:.96rem}.overview-note p,.agency-head p,.region-row p{margin:5px 0 0;color:var(--theme-muted,#71839a);font-size:.8rem;line-height:1.5}.overview-note>span{white-space:nowrap;background:var(--theme-soft,#eaf0fc);border:1px solid var(--theme-line,#dbe5f6);padding:7px 11px;border-radius:7px;color:var(--theme-muted,#44638d);font-size:.75rem}.agency-group{background:var(--theme-surface,#fff);border:1px solid var(--theme-line,#dce5f1);border-radius:14px;overflow:hidden;margin-bottom:18px}.agency-head{display:flex;gap:13px;align-items:center;padding:19px 22px;border-bottom:1px solid var(--theme-line,#e5ebf4)}.agency-icon{display:grid;place-items:center;width:42px;height:42px;flex:none;border-radius:10px;background:var(--theme-soft,#edf3ff);color:var(--theme-accent,#3469c3)}.agency-head h2{font-size:1rem;margin:0;line-height:1.4}.region-row{display:grid;grid-template-columns:minmax(0,1fr) 230px auto;gap:24px;align-items:center;padding:20px 22px;border-bottom:1px solid var(--theme-line,#e9eef5)}.region-row:last-child{border:0}.region-identity{display:flex;align-items:center;gap:15px;min-width:0}.region-tag{display:inline-flex;align-items:center;justify-content:center;min-width:57px;padding:7px 9px;background:var(--theme-soft,#edf3ff);color:var(--theme-accent,#2456ab);border-radius:7px;font-size:.73rem;font-weight:800;flex:none}.region-row h3{margin:0;font-size:.86rem;line-height:1.5;overflow-wrap:anywhere}.range{display:grid;gap:6px}.range span{color:var(--theme-muted,#71839a);font-size:.72rem}.range strong{font-size:.88rem;font-variant-numeric:tabular-nums}.secondary,.primary{display:inline-flex;align-items:center;justify-content:center;gap:14px;min-height:40px;padding:10px 14px;border-radius:8px;font-size:.78rem;font-weight:750;white-space:nowrap}.secondary{border:1px solid var(--theme-line,#cad8ee);background:var(--theme-surface,#fff);color:var(--theme-accent,#2b5591)}.secondary:hover{background:var(--theme-soft,#f3f7ff);border-color:#96b7ed}.primary{border:1px solid #2563eb;background:#2563eb;color:#fff}.back{padding:0;background:none;border:0;color:var(--theme-accent,#2b60b5);font-size:.79rem;font-weight:750;margin:18px 0}.detail-head{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 24px;background:var(--theme-surface,#fff);border:1px solid var(--theme-line,#dce5f1);border-radius:12px}.eyebrow{font-size:.7rem;color:var(--theme-muted,#55739e);margin:0;font-weight:750}.detail-head h2{margin:6px 0;font-size:1.35rem}.region-name{margin:0;color:var(--theme-muted,#71839a);font-size:.8rem}.detail-note{padding:13px 16px;margin:16px 0;background:var(--theme-soft,#edf4ff);border-radius:9px;color:var(--theme-muted,#476488);font-size:.78rem;line-height:1.6}.detail-meta{display:flex;justify-content:space-between;gap:12px;margin:21px 0 12px;font-size:.77rem}.detail-meta span{color:var(--theme-muted,#71839a)}.position-table-wrap{overflow:auto;border:1px solid var(--theme-line,#dce5f1);border-radius:12px;background:var(--theme-surface,#fff)}.position-table{width:100%;min-width:1020px;border-collapse:collapse}.position-table th{padding:14px 12px;background:var(--theme-soft,#f5f8fd);color:var(--theme-muted,#627b9b);text-transform:uppercase;font-size:.64rem;text-align:left;white-space:nowrap}.position-table td{padding:17px 12px;font-size:.79rem;vertical-align:middle;border-top:1px solid var(--theme-line,#e9eef5)}.position-table td:first-child{min-width:165px}.position-table td strong{display:block;font-size:.83rem}.position-table small{display:block;margin-top:5px;color:var(--theme-muted,#71839a);font-size:.69rem}.amount{font-variant-numeric:tabular-nums;white-space:nowrap;font-weight:650}.status{display:inline-flex;align-items:center;padding:5px 9px;background:#e2f6eb;color:#157445;border-radius:20px;font-size:.66rem;font-weight:750}.status.inactive{background:var(--theme-soft,#edf1f7);color:var(--theme-muted,#718096)}.actions{display:flex;align-items:center;gap:7px}.actions button{display:grid;place-items:center;flex:none;width:34px;height:34px;padding:0;border:1px solid var(--theme-line,#d3deee);border-radius:8px;background:var(--theme-surface,#fff);color:var(--theme-accent,#385c8c)}.actions svg{width:16px;height:16px}.actions button:hover:not(:disabled){background:var(--theme-soft,#edf3ff);border-color:#99b7e7}.actions .danger:hover:not(:disabled){background:#fff1f2;color:#b53636;border-color:#edb9b9}.empty{padding:32px 20px;border:1px solid var(--theme-line,#dce5f1);border-radius:12px;background:var(--theme-surface,#fff);text-align:center;color:var(--theme-muted,#71839a);font-size:.85rem;line-height:1.6}.position-cards{display:none}.position-card{background:var(--theme-surface,#fff);border:1px solid var(--theme-line,#dce5f1);border-radius:12px;overflow:hidden}.position-card header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:16px;border-bottom:1px solid var(--theme-line,#e9eef5)}.position-card header strong{font-size:.86rem}.position-card dl{margin:0;display:grid;gap:11px;padding:16px}.position-card dl div{display:flex;justify-content:space-between;gap:10px;font-size:.79rem}.position-card dt{color:var(--theme-muted,#71839a)}.position-card dd{margin:0;font-weight:750}.effective{margin:0;padding:0 16px 15px;color:var(--theme-muted,#71839a);font-size:.72rem;line-height:1.6}.position-card footer{justify-content:flex-end;border-top:1px solid var(--theme-line,#e9eef5);padding:12px 16px}@media(max-width:1100px){.region-row{grid-template-columns:minmax(0,1fr) auto;gap:16px}.range{grid-column:1;grid-row:2}.region-row>.secondary{grid-column:2;grid-row:1/3}.position-table-wrap{display:none}.position-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}}@media(max-width:650px){.overview-note{align-items:flex-start}.agency-head{padding:16px}.agency-head h2{font-size:.88rem}.region-row{padding:16px;grid-template-columns:1fr;gap:14px}.region-identity{align-items:flex-start;gap:10px}.region-row>.secondary{grid-column:1;grid-row:auto;justify-content:space-between}.range{grid-row:auto;grid-template-columns:1fr auto;align-items:center;gap:10px}.detail-head{padding:18px;align-items:stretch;flex-direction:column;gap:15px}.detail-head h2{font-size:1.2rem}.detail-head>.primary{width:100%}.detail-meta{font-size:.72rem}.position-cards{grid-template-columns:1fr}}
.regional-summary{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:16px;padding:22px 24px;border:1px solid var(--theme-line,#dce5f1);border-radius:12px;background:var(--theme-surface,#fff)}.regional-summary>div>strong{display:block;margin:8px 0;color:var(--theme-accent,#255494);font-size:1.5rem;font-variant-numeric:tabular-nums}.regional-summary small,.range small{display:block;color:var(--theme-muted,#71839a);font-size:.74rem;line-height:1.5}.regional-buttons{display:flex;flex-wrap:wrap;gap:8px}.region-controls{display:grid;justify-items:end;gap:9px}.setup-link{border:0;padding:2px;background:none;color:var(--theme-accent,#2563eb);font-size:.77rem;font-weight:650}.region-controls .secondary{width:100%;justify-content:space-between}.range small{margin-top:0}@media(max-width:1100px){.region-controls{grid-column:2;grid-row:1/3}}@media(max-width:650px){.region-controls{grid-column:1;grid-row:auto;justify-items:stretch}.region-controls .actions{justify-content:flex-end}.regional-summary{align-items:stretch;flex-direction:column;padding:18px}.regional-buttons .secondary{flex:1}.range small{grid-column:1/-1}}
</style>
